package com.iare.club;
import com.iare.club.entity.*;import com.iare.club.repository.*;import com.iare.club.service.*;import java.math.BigDecimal;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.transaction.annotation.Transactional;import static org.assertj.core.api.Assertions.*;
@SpringBootTest @Transactional class UpiPaymentFeatureTests{
 @Autowired UpiPaymentService payments;@Autowired UserRepository users;@Autowired WalletService wallets;@Autowired WalletTransactionRepository transactions;
 AppUser user;
 @BeforeEach void setup(){user=new AppUser();user.setFullName("UPI Tester");user.setEmail("upi-"+System.nanoTime()+"@example.com");user.setPasswordHash("test");user=users.save(user);}
 @Test void qrUriContainsConfiguredDestinationAmountPayeeAndUniqueReference(){UpiPaymentRequest p=payments.create(user,new BigDecimal("100.00"));String uri=payments.uri(p);assertThat(uri).contains("pa=fundraiser%40upi","pn=Fundraiser","am=100.00","cu=INR","tr="+p.getReference());assertThat(payments.qr(p)).isNotEmpty();}
 @Test void configuredUpiIdAndPayeeAreStoredOnEveryPendingRequest(){UpiPaymentRequest payment=payments.create(user,new BigDecimal("10.00"));assertThat(payment.getMerchantUpiId()).isEqualTo("fundraiser@upi");assertThat(payment.getMerchantName()).isEqualTo("Fundraiser");assertThat(payment.getStatus()).isEqualTo(UpiPaymentRequest.Status.PENDING);}
 @Test void youpiObservationNeverCreditsWallet(){UpiPaymentRequest p=payments.create(user,new BigDecimal("100.00"));payments.observeYoupi(p.getReference(),"signal-1","123456789012","OBSERVED_SUCCESS","NOT_RECONCILED");assertThat(payments.forUser(p.getReference(),user).getStatus()).isEqualTo(UpiPaymentRequest.Status.DETECTED_UNVERIFIED);assertThat(wallets.getOrCreate(user).getDepositBalance()).isEqualByComparingTo("0.00");assertThat(transactions.existsByReference(p.getReference())).isFalse();}
 @Test void reviewedBankRecordCreditsExactlyOnce(){UpiPaymentRequest p=payments.create(user,new BigDecimal("100.00"));payments.manualVerify(p.getId(),"BANK-TXN-1","123456789012","Matched official bank statement row", "admin@example.com");payments.manualVerify(p.getId(),"BANK-TXN-1","123456789012","Repeated review of same bank statement", "admin@example.com");assertThat(wallets.getOrCreate(user).getDepositBalance()).isEqualByComparingTo("100.00");assertThat(transactions.existsByReference(p.getReference())).isTrue();}
}
